صنف مركبة {
    دالة بناء(اسم، سرعة) {
        هذا.اسم = اسم
        هذا.سرعة = سرعة
    }
    دالة وصف() {
        أرجع هذا.اسم + ":" + نص(هذا.سرعة)
    }
