صنف حساب_بنكي {
    دالة بناء(المالك، رصيد_أولي = 100) {
        هذا.المالك = المالك
        هذا.الرصيد = رصيد_أولي
    }
    دالة إيداع(مبلغ) {
        هذا.الرصيد = هذا.الرصيد + مبلغ
        أرجع هذا.الرصيد
    }
    دالة سحب(مبلغ) {
        إذا (مبلغ <= هذا.الرصيد) {
            هذا.الرصيد = هذا.الرصيد - مبلغ
        }
        أرجع هذا.الرصيد
    }
}
دع حساب = جديد حساب_بنكي("سارة")
حساب.إيداع(50)
حساب.سحب(30)
اطبع(ن"{حساب.المالك}:{حساب.الرصيد}")

